import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

const UserViewProfile = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [profile, setProfile] = useState(null);

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/profile/${id}`);
        setUser(res.data.user);
        setProfile(res.data.profile);
      } catch (err) {
        console.error("Error fetching user profile:", err);
      }
    };
    fetchProfile();
  }, [id]);

  return (
    <div className="profile-container">
      <h2 className="profile-title">User Profile</h2>
      {user && (
        <>
          <p><b>Username:</b> {user.username}</p>
          <p><b>Email:</b> {user.email}</p>
        </>
      )}
      {profile && (
        <>
          <p><b>Bio:</b> {profile.bio}</p>
          <p><b>Genres:</b> {profile.genres?.join(", ")}</p>
          <p><b>Instruments:</b> {profile.instruments?.join(", ")}</p>
          <p><b>Years of Experience:</b> {profile.yearsOfExperience || "N/A"}</p>
          {profile.youtube && (
            <p><b>YouTube:</b> <a href={profile.youtube} target="_blank" rel="noopener noreferrer">{profile.youtube}</a></p>
          )}
          {profile.instagram && (
            <p><b>Instagram:</b> <a href={profile.instagram} target="_blank" rel="noopener noreferrer">{profile.instagram}</a></p>
          )}
        </>
      )}

      {/* ✅ Back Button */}
      <button
        onClick={() => navigate(-1)}
        style={{
          marginTop: "20px",
          padding: "10px 20px",
          backgroundColor: "#f97316",
          color: "white",
          border: "none",
          borderRadius: "6px",
          cursor: "pointer",
          fontWeight: "bold"
        }}
      >
        ⬅️ Back
      </button>
    </div>
  );
};

export default UserViewProfile;
